/**
 * EXTERNAL EVALUATION — a published third-party dataset the rules were never written against
 *
 * Set B guards against snooping inside this project, but it was still authored here. This
 * harness scores the live classifier on data somebody else produced:
 *
 *   HttpParamsDataset (Morzeux, 2016, MIT licence) — https://github.com/Morzeux/HttpParamsDataset
 *   31,067 HTTP parameter values: 19,304 benign (taken from CSIC 2010 benign requests) and
 *   11,763 attacks generated by sqlmap, XSSYA, Vega and FuzzDB (SQLi, XSS, command injection,
 *   path traversal).
 *
 * Rules of the run, so the number cannot be flattered
 *   - The dataset is not in the repository and no rule was written or changed against it.
 *     Its SHA-256 is printed, so a reader can confirm which file was scored.
 *   - Every sample is sent once, with the neutral vector UNKNOWN and a rotating source
 *     address: the label never reaches the classifier (same method as eval_holdout_b).
 *   - The decision rule is fixed in advance and identical to the other harnesses: any
 *     verdict other than ALLOW counts as a detection.
 *   - A request that fails is scored against the system (attack → missed, benign → false
 *     alarm), not dropped.
 *   - Duplicates are kept, as published; the de-duplicated figure is printed beside it.
 *
 * Run:  ADMIN_API_KEY=... npx tsx audit/eval_external_httpparams.ts <path/to/payload_full.csv> [out.json]
 */

import fs from 'fs';
import crypto from 'crypto';

const BASE = 'http://127.0.0.1:3000';
const KEY = process.env.ADMIN_API_KEY || 'test_admin_key_123';
const CONCURRENCY = 10;
const PREVALENCE = 0.02;

interface Row { payload: string; attackType: string; malicious: boolean; }

/** RFC 4180: quoted fields, doubled quotes, commas and newlines inside quotes. */
function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else quoted = false;
      } else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); rows.push(row); row = []; field = '';
    } else field += c;
  }
  if (field || row.length) { row.push(field); rows.push(row); }
  return rows;
}

/** Wilson score interval, 95%. */
function wilson(k: number, n: number): [number, number] {
  if (n === 0) return [0, 0];
  const z = 1.96, p = k / n;
  const d = 1 + (z * z) / n;
  const c = p + (z * z) / (2 * n);
  const m = z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n));
  return [(c - m) / d, (c + m) / d];
}

const pct = (x: number) => (x * 100).toFixed(2) + '%';
const ci = ([a, b]: [number, number]) => `[${pct(a)} – ${pct(b)}]`;

async function classify(payload: string, n: number): Promise<{ detected: boolean; ok: boolean }> {
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch(`${BASE}/api/v1/agent/ai-analyze`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': KEY },
        body: JSON.stringify({
          packet: {
            srcIp: `10.40.${(n >> 8) & 255}.${n & 255}`,
            dstIp: '10.0.1.10',
            port: 443,
            protocol: 'HTTPS',
            vector: 'UNKNOWN',
            payload
          }
        }),
        signal: AbortSignal.timeout(30000)
      });
      if (!res.ok) continue;
      const d: any = await res.json().catch(() => null);
      if (!d?.verdict) continue;
      return { detected: String(d.verdict) !== 'ALLOW', ok: true };
    } catch {
      /* retried once, then scored against the system */
    }
  }
  return { detected: false, ok: false };
}

(async () => {
  const file = process.argv[2];
  if (!file || !fs.existsSync(file)) {
    console.error('Usage: npx tsx audit/eval_external_httpparams.ts <payload_full.csv> [out.json]');
    process.exit(2);
  }
  const health = await fetch(`${BASE}/api/health`).catch(() => null);
  if (!health?.ok) { console.error(`Server not reachable at ${BASE}.`); process.exit(2); }

  const raw = fs.readFileSync(file);
  const sha256 = crypto.createHash('sha256').update(raw).digest('hex');
  const table = parseCsv(raw.toString('utf-8')).filter(r => r.length >= 4);
  const header = table.shift()!;
  const [iP, iT, iL] = ['payload', 'attack_type', 'label'].map(h => header.indexOf(h));
  const rows: Row[] = table.map(r => ({ payload: r[iP], attackType: r[iT], malicious: r[iL] === 'anom' }));

  const t0 = Date.now();
  const results: Array<Row & { detected: boolean; ok: boolean }> = new Array(rows.length);
  let next = 0;
  await Promise.all(Array.from({ length: CONCURRENCY }, async () => {
    for (;;) {
      const i = next++;
      if (i >= rows.length) return;
      results[i] = { ...rows[i], ...(await classify(rows[i].payload, i)) };
      if (i > 0 && i % 5000 === 0) console.error(`  ${i}/${rows.length}`);
    }
  }));
  const seconds = (Date.now() - t0) / 1000;

  // A failed request counts against the system: an attack it did not flag, or a benign value
  // it did not clear.
  const flagged = (r: (typeof results)[number]) => (r.ok ? r.detected : !r.malicious);
  const score = (set: typeof results) => {
    const tp = set.filter(r => r.malicious && flagged(r)).length;
    const fn = set.filter(r => r.malicious && !flagged(r)).length;
    const fp = set.filter(r => !r.malicious && flagged(r)).length;
    const tn = set.filter(r => !r.malicious && !flagged(r)).length;
    const precision = tp / (tp + fp || 1);
    const recall = tp / (tp + fn || 1);
    const f1 = (2 * precision * recall) / (precision + recall || 1);
    const fpr = fp / (fp + tn || 1);
    const accuracy = (tp + tn) / set.length;
    const mcc = (tp * tn - fp * fn) / Math.sqrt((tp + fp) * (tp + fn) * (tn + fp) * (tn + fn) || 1);
    const projPrecision = (recall * PREVALENCE) / (recall * PREVALENCE + fpr * (1 - PREVALENCE) || 1);
    return {
      n: set.length, tp, fn, fp, tn, precision, recall, f1, fpr, accuracy, mcc,
      recallCI: wilson(tp, tp + fn), precisionCI: wilson(tp, tp + fp), fprCI: wilson(fp, fp + tn),
      projectedPrecisionAt2pct: projPrecision, falseAlarmsPer10k: fpr * (1 - PREVALENCE) * 10000
    };
  };

  const all = score(results);
  const seen = new Set<string>();
  const dedup = score(results.filter(r => {
    const k = `${r.malicious}|${r.payload}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  }));
  const byType: Record<string, { n: number; detected: number; rate: number; ci: [number, number] }> = {};
  for (const t of [...new Set(results.map(r => r.attackType))]) {
    const set = results.filter(r => r.attackType === t);
    const detected = set.filter(flagged).length;
    byType[t] = { n: set.length, detected, rate: detected / set.length, ci: wilson(detected, set.length) };
  }
  const failed = results.filter(r => !r.ok).length;
  const missedExamples = results.filter(r => r.malicious && !flagged(r)).slice(0, 12).map(r => `${r.attackType}: ${r.payload.slice(0, 90)}`);
  const fpExamples = results.filter(r => !r.malicious && flagged(r)).slice(0, 12).map(r => r.payload.slice(0, 90));

  const out = {
    dataset: 'HttpParamsDataset (Morzeux, 2016, MIT)', file, sha256,
    samples: rows.length, failedRequests: failed, seconds: +seconds.toFixed(1),
    samplesPerSecond: +(rows.length / seconds).toFixed(1),
    all, deduplicated: dedup, byType, missedExamples, fpExamples, finishedAt: new Date().toISOString()
  };
  if (process.argv[3]) fs.writeFileSync(process.argv[3], JSON.stringify(out, null, 2));

  console.log('\n' + '='.repeat(76));
  console.log('  EXTERNAL DATASET — HttpParamsDataset (never used to write any rule)');
  console.log('='.repeat(76));
  console.log(`  file sha256   ${sha256}`);
  console.log(`  samples       ${rows.length}  (${failed} failed requests, scored against the system)`);
  console.log(`  time          ${seconds.toFixed(1)} s  (${(rows.length / seconds).toFixed(1)} samples/s)`);
  console.log(`\n  confusion     TP ${all.tp}  FN ${all.fn}  FP ${all.fp}  TN ${all.tn}`);
  console.log(`  precision     ${pct(all.precision)}  95% CI ${ci(all.precisionCI)}`);
  console.log(`  recall        ${pct(all.recall)}  95% CI ${ci(all.recallCI)}`);
  console.log(`  F1            ${pct(all.f1)}`);
  console.log(`  FPR           ${pct(all.fpr)}  95% CI ${ci(all.fprCI)}`);
  console.log(`  accuracy      ${pct(all.accuracy)}   MCC ${all.mcc.toFixed(4)}`);
  console.log(`  at 2% prevalence: analyst-visible precision ${pct(all.projectedPrecisionAt2pct)}, false alarms per 10,000 requests ${all.falseAlarmsPer10k.toFixed(1)}`);
  console.log(`\n  de-duplicated (${dedup.n} unique): precision ${pct(dedup.precision)}  recall ${pct(dedup.recall)}  F1 ${pct(dedup.f1)}  FPR ${pct(dedup.fpr)}`);
  console.log('\n  by class (detected / total)');
  for (const [t, v] of Object.entries(byType)) {
    console.log(`    ${t.padEnd(16)} ${String(v.detected).padStart(6)} / ${String(v.n).padEnd(6)} ${pct(v.rate)}  CI ${ci(v.ci)}${t === 'norm' ? '   <- flagged benign = false alarms' : ''}`);
  }
  console.log('\n  missed attacks (first 12)');
  for (const m of missedExamples) console.log('    ' + m);
  console.log('\n  false alarms (first 12)');
  for (const m of fpExamples) console.log('    ' + m);
  process.exit(0);
})();
